#!/bin/bash\n# Cloudless.gr Secret Configuration Script\n# This script automates the configuration of required secrets for the migration\n\nset -e\n\necho \"🚀 Starting Cloudless.gr secret configuration...\"\necho \"\"\n\n# Colors for output\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nRED='\\033[0;31m'\nNC='\\033[0m' # No Color\n\n# Check if we're in the cloudless.gr directory\nif [ ! -f \"wrangler.jsonc\" ]; then\n    echo -e \"${RED}❌ Error: Not in cloudless.gr directory${NC}\"\n    echo \"Please run this script from the cloudless.gr root directory\"\n    exit 1\nfi\n\necho \"✅ Detected cloudless.gr repository\"\necho \"\"\n\n# Function to add GitHub secrets\necho -e \"${YELLOW}📌 Step 1: Adding GitHub Secrets${NC}\"\necho \"\"\n\ncat << 'EOF'\nGitHub Secrets Required:\n1. CLOUDflare_API_TOKEN - Cloudflare API token for deployments\n2. CF_ACCOUNT_ID - Cloudflare account ID\n\nThese secrets are used in:\n- .github/workflows/deploy-cloudflare.yml (lines 38, 72)\n- .github/workflows/preview.yml (lines 47, 82)\n\nEOF\n\n# Check if secrets are already configured\nif [ -n \"${{secrets.CLOUDflare_API_TOKEN}}\" ]; then\n    echo -e \"${GREEN}✅ CLOUDflare_API_TOKEN is already configured${NC}\"\nelse\n    echo -e \"${YELLOW}⚠️  CLOUDflare_API_TOKEN not found in GitHub secrets${NC}\"\n    echo \"\"\n    echo \"To add GitHub secrets:\"\n    echo \"1. Go to: https://github.com/Themis128/cloudless.gr/settings/secrets/actions\"\n    echo \"2. Click 'New repository secret'\"\n    echo \"3. Add secrets one by one:\"\n    echo \"   - Name: CLOUDflare_API_TOKEN, Value: [your Cloudflare API token]\"\n    echo \"   - Name: CF_ACCOUNT_ID, Value: c6d6b805741159c062a3e0b0d7f9d89a\"\n    echo \"\"\n    echo \"Or use GitHub CLI:\"\n    echo \"gh secret set CLOUDflare_API_TOKEN -b \\\"your-token-here\\\"\"\n    echo \"gh secret set CF_ACCOUNT_ID -b \\\"c6d6b805741159c062a3e0b0d7f9d89a\\\"\"\n    echo \"\"\nfi\n\n# Function to add Wrangler secret\necho -e \"${YELLOW}📌 Step 2: Adding Wrangler Secret (GOOGLE_PRIVATE_KEY)${NC}\"\necho \"\"\n\ncat << 'EOF'\nWrangler Secret Required:\n- GOOGLE_PRIVATE_KEY - Google Calendar service account private key\n\nThis secret is used in:\n- Calendar booking functionality\n- Google Calendar API authentication\n\nFormat: The private key should include \\\\n for newlines\nExample:\n-----BEGIN PRIVATE KEY-----\\nMIIEvQIBADANBgkqhkiG9w0BAQEFAASCBKcwggSjAgEAAoIBAQC...\n-----END PRIVATE KEY-----\n\nEOF\n\nif wrangler secret list 2>/dev/null; then\n    if wrangler secret get GOOGLE_PRIVATE_KEY >/dev/null 2>&1; then\n        echo -e \"${GREEN}✅ GOOGLE_PRIVATE_KEY is already configured as Wrangler secret${NC}\"\n    else\n        echo -e \"${YELLOW}⚠️  GOOGLE_PRIVATE_KEY not found as Wrangler secret${NC}\"\n        echo \"\"\n        echo \"To add Wrangler secret:\"\n        echo \"1. Run: wrangler secret put GOOGLE_PRIVATE_KEY --config wrangler.jsonc\"\n        echo \"2. Paste your Google service account private key when prompted\"\n        echo \"   Make sure to include \\\\n for newlines in the key\"\n        echo \"\"\n        echo \"Example command:\"\n        echo \"cat google-service-account.json | jq -r '.private_key' | wrangler secret put GOOGLE_PRIVATE_KEY --config wrangler.jsonc\"\n        echo \"\"\n    fi\nelse\n    echo -e \"${RED}❌ Wrangler not found or not authenticated${NC}\"\n    echo \"Install Wrangler with: npm install -g wrangler\"\n    echo \"Login with: wrangler login\"\n    echo \"\"\nfi\n\n# Function to populate D1 configuration\necho -e \"${YELLOW}📌 Step 3: Populating D1 Configuration${NC}\"\necho \"\"\n\ncat << 'EOF'\nD1 Configuration Required:\n- GOOGLE_CLIENT_EMAIL - Google Calendar service account email\n- GOOGLE_CALENDAR_ID - Calendar ID (usually 'primary')\n\nThese values are stored in the app_config table (migration 0007)\n\nEOF\n\nif command -v sqlite3 &>/dev/null || command -v wrangler &>/dev/null; then\n    echo -e \"${YELLOW}⚠️  Checking if D1 is accessible...${NC}\"\n    \n    # Try to check if values are populated\n    if command -v wrangler &>/dev/null; then\n        if wrangler d1 execute user-auth-db --command \"SELECT value FROM app_config WHERE key='GOOGLE_CLIENT_EMAIL';\" --remote 2>/dev/null | grep -q .; then\n            echo -e \"${GREEN}✅ D1 app_config table is accessible${NC}\"\n        else\n            echo -e \"${YELLOW}⚠️  Cannot access D1 directly${NC}\"\n            echo \"D1 is accessible via Workers API or through the application\"\n        fi\n    fi\n    \n    echo \"\"\n    echo \"To populate D1 values:\"\n    echo \"1. Run in cloudless.gr root:\"\n    echo \"\"\n    echo \"# For Google Calendar service account email:\"\n    echo \"npx wrangler d1 execute user-auth-db --file ./migrations/0007-app-config.sql --remote --config wrangler.jsonc\"\n    echo \"\"\n    echo \"# Or manually insert values:\"\n    echo \"npx wrangler d1 execute user-auth-db --command \\\"INSERT OR REPLACE INTO app_config (key, value, description) VALUES ('GOOGLE_CLIENT_EMAIL', 'your-service-account@project.iam.gserviceaccount.com', 'Google Calendar service account email');\\\" --remote --config wrangler.jsonc\"\n    echo \"\"\n    echo \"npx wrangler d1 execute user-auth-db --command \\\"INSERT OR REPLACE INTO app_config (key, value, description) VALUES ('GOOGLE_CALENDAR_ID', 'primary', 'Google Calendar ID');\\\" --remote --config wrangler.jsonc\"\n    echo \"\"\nelse\n    echo -e \"${RED}❌ Neither sqlite3 nor wrangler found${NC}\"\n    echo \"Install Wrangler: npm install -g wrangler\"\n    echo \"\"\nfi\n\necho -e \"${YELLOW}📌 Step 4: Verification${NC}\"\necho \"\"\n\necho \"After adding all secrets, verify with:\"\necho \"\"\necho \"# Check GitHub secrets:\"\necho \"gh secret list\"\necho \"\"\necho \"# Check Wrangler secrets:\"\necho \"wrangler secret list --config wrangler.jsonc\"\necho \"\"\necho \"# Check D1 configuration:\"\necho \"npx wrangler d1 execute user-auth-db --command 'SELECT key, value FROM app_config WHERE key LIKE \\\"GOOGLE%\\\"' --remote --config wrangler.jsonc\"\necho \"\"\n\necho -e \"${GREEN}✅ Configuration script completed!${NC}\"\necho \"\"\necho \"Next steps:\"\necho \"1. Add the missing secrets using the commands above\"\necho \"2. Run the verification commands to confirm configuration\"\necho \"3. Test the calendar booking functionality\"\necho \"\"\n\necho -e \"${YELLOW}📝 Quick Reference:${NC}\"\necho \"GitHub Secrets: CLOUDflare_API_TOKEN, CF_ACCOUNT_ID\"\necho \"Wrangler Secret: GOOGLE_PRIVATE_KEY\"\necho \"D1 Values: GOOGLE_CLIENT_EMAIL, GOOGLE_CALENDAR_ID\"\n}\n